cat << 'EOF' > patch.js
const fs = require('fs');

let content = fs.readFileSync('src/orchestration/tools/registry.ts', 'utf8');

// fix imports
content = content.replace(
  "import {Ajv, type Options, type ValidateFunction, type ErrorObject} from 'ajv';",
  "import Ajv, {type ValidateFunction, type ErrorObject} from 'ajv';"
);

// fix Ajv instantiation
content = content.replace(
  /const ajvOptions: Options = \{\n  strict: false,\n  validateFormats: false,\n\};\nconst ajv = new Ajv\(ajvOptions\);/,
  "const ajv = new Ajv({\n  strict: false,\n  validateFormats: false,\n});"
);

// fix compileSchema
content = content.replace(
  /private compileSchema\(toolName: string, schema: object\): ValidateFunction \{[\s\S]*?return validate;\n  \}/,
  `private compileSchema(toolName: string, schema: object): ValidateFunction {
    const cached = this.schemaCache.get(schema);
    if (cached) return cached;
    try {
      const validate = ajv.compile(schema);
      this.schemaCache.set(schema, validate);
      return validate;
    } catch (error) {
      throw new Error(
        \`Invalid inputSchema for tool \${toolName}: \${error instanceof Error ? error.message : String(error)}\`,
        {cause: error}
      );
    }
  }`
);

// fix execute error.instancePath
content = content.replace(
  /const error = validate\.errors\?\.\[0\] as ErrorObject \| undefined;\n      const property =\n        \(error\?\.params as Record<string, unknown>\)\?\.\['missingProperty'\] \|\| error\?\.instancePath \|\| 'input';/,
  `const error = validate.errors?.[0] as any;
      const property =
        (error?.params as Record<string, unknown>)?.['missingProperty'] || error?.instancePath || error?.dataPath || 'input';`
);

fs.writeFileSync('src/orchestration/tools/registry.ts', content);
EOF
node patch.js

